import { cx } from "../../lib/format";
import styles from "./IconSprite.module.css";

/**
 * Every icon the client uses, as `<symbol id="i-<name>">` entries that
 * `<Icon name>` references with `<use href="#i-<name>">`. Render it once, at
 * the top of the app. Kept hidden without `display: none`, which would stop
 * `<use>` from resolving.
 *
 * The artwork comes from the design team's icon library (icon-library.html):
 * a 24x24 canvas, no colour of its own, every stroke and fill `currentColor`.
 * 48 of the 76 names below are drawn from it.
 *
 * ICON_NAMES is a DOM contract, so the names never move with the artwork. The
 * 28 below have no counterpart in the library yet and still use the older
 * in-house drawing; swap each one over once the library gains it.
 */
export const MISSING_FROM_LIBRARY = [
	"sidebar",
	"newChat",
	"back",
	"external",
	"upgrade",
	"fork",
	"send",
	"stop",
	"folderPlus",
	"up",
	"tree",
	"open",
	"listCheck",
	"layers",
	"orbit",
	"paperclip",
	"cube",
	"zap",
	"wrap",
	"panelRight",
	"tag",
	"puzzle",
	"fileDiff",
	"openExternal",
	"mcp",
	"palette",
	"wand",
	"prompt",
] as const;

/*
 * What each gap needs, for the design team:
 * - sidebar: 侧边栏开关（左侧面板）
 * - newChat: 新建对话（气泡 + 加号）
 * - back: 返回（左箭头带尾，区别于左向尖括号）
 * - external: 外链（右上斜箭头）
 * - upgrade: 升级（右上斜箭头出框）
 * - fork: 分支 / fork（Git 分叉）
 * - send: 发送（向上箭头，带尾）
 * - stop: 停止（实心圆角方块）
 * - folderPlus: 新建文件夹（文件夹 + 加号）
 * - up: 向上箭头（带尾）
 * - tree: 文件树（层级缩进线）
 * - open: 展开的文件夹
 * - listCheck: 任务清单（列表 + 对勾）
 * - layers: 图层（多层堆叠）
 * - orbit: 轨道 / 环绕（椭圆轨道 + 卫星）
 * - paperclip: 附件（回形针）
 * - cube: 立方体 / 模型（3D 方块）
 * - zap: 闪电
 * - wrap: 自动换行
 * - panelRight: 右侧面板开关
 * - tag: 标签（吊牌）
 * - puzzle: 插件（拼图块）
 * - fileDiff: 文件差异（文件 + 加减号）
 * - openExternal: 在新窗口打开（方框 + 右上斜箭头）
 * - mcp: MCP 品牌标识
 * - palette: 调色板 / 外观主题
 * - wand: 魔法棒（技能 Skills）
 * - prompt: 命令提示符（无边框的 ›_ ，区别于带框终端）
 */

